/**
 * @brief Print operand
 * @param out File to print to
 * @param op operand
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Track the frame location chosen for each IR value.
typedef struct {
  IrStackSlotId slot;
  // AI generated by: Codex (GPT-6.2-sol)
  // Prompt: "Implement all"
  // Changes: Record the last use of each reusable frame location.
  size_t local;
  size_t live_through;
} CgPlacement;

/**
 * @brief Write the frame operand assigned to a value by placement planning.
 */
static void cg_print_value(FILE* out,
                           const CgPlacement* placement,
                           IrValueId id) {
  if (placement[id].slot != IR_INVALID_ID) {
    cg_print_localframe_slot(out, placement[id].slot);
  } else {
    cg_print_localframe_val(out, placement[id].local);
  }
}

/**
 * @brief Write a literal or resolve a value through the placement plan.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Thread value placement through this emitter.
static void cg_print_operand(FILE* out,
                             const CgPlacement* placement,
                             IrOperand* op) {
  switch (op->type) {
    case IR_OP_VALUE:
      cg_print_value(out, placement, op->value.id);
      break;
    case IR_OP_INT32:
      cg_print_int(out, op->value.int32_value);
      break;
    case IR_OP_DOUBLE:
      cg_print_float(out, op->value.double_value);
      break;
    case IR_OP_BOOL:
      cg_print_bool(out, op->value.bool_value);
      break;
    case IR_OP_STRING:
      cg_print_string(out, op->value.string_value);
      break;
    case IR_OP_UNIT:
      cg_print_nil(out);
      break;
  }
}

// Instructions

/**
 * @brief Print unary instruction
 * @param out File to print to
 * @param opcode opcode
 * @param inst instruction
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Thread value placement through this emitter.
static void cg_print_unary_inst(FILE* out,
                                const CgPlacement* placement,
                                char* opcode,
                                IrInstruction* inst) {
  if (inst->result == IR_INVALID_ID) {
    return;
  }
  fputs(opcode, out);
  cg_print_ws(out);
  cg_print_value(out, placement, inst->result);
  cg_print_ws(out);
  cg_print_operand(out, placement, &inst->operands.unary.operand);
  cg_print_nl(out);
}

/**
 * @brief Print binary instruction
 * @param out File to print to
 * @param opcode opcode
 * @param inst instruction
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Thread value placement through this emitter.
static void cg_print_binary_inst(FILE* out,
                                 const CgPlacement* placement,
                                 char* opcode,
                                 IrInstruction* inst) {
  if (inst->result == IR_INVALID_ID && strcmp(opcode, "DIV") != 0 &&
      strcmp(opcode, "IDIV") != 0) {
    return;
  }
  fputs(opcode, out);
  cg_print_ws(out);
  if (inst->result == IR_INVALID_ID) {
    fputs("GF@$tmp1", out);
  } else {
    cg_print_value(out, placement, inst->result);
  }
  cg_print_ws(out);
  cg_print_operand(out, placement, &inst->operands.binary.left);
  cg_print_ws(out);
  cg_print_operand(out, placement, &inst->operands.binary.right);
  cg_print_nl(out);
}

