/**
 * @brief Print inline builtin function execution
 * @param out File to print to
 * @param inst instruction
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Read the statically known source type for typed builtin emission.
static IrType cg_operand_type(IrFunction* fn, const IrOperand* operand) {
  switch (operand->type) {
    case IR_OP_INT32:
      return IR_INT;
    case IR_OP_DOUBLE:
      return IR_DOUBLE;
    case IR_OP_BOOL:
      return IR_BOOL;
    case IR_OP_STRING:
      return IR_STRING;
    case IR_OP_UNIT:
      return IR_UNIT;
    case IR_OP_VALUE: {
      IrInstruction* definition =
          optimizer_find_definition(fn, operand->value.id);
      return definition ? definition->result_type : (IrType)-1;
    }
  }

  return (IrType)-1;
}

/**
 * @brief Recognize a constant one-character slice suitable for a single
 * GETCHAR.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Pass the function to builtin selection for static operand types.
// Thread value placement through this emitter.
// Recognize a fixed one-character substring without overflowing the
// index.
static bool cg_single_character_substring(const IrInstruction* inst) {
  const IrOperand* args = inst->operands.call.args;
  return args[1].type == IR_OP_INT32 && args[2].type == IR_OP_INT32 &&
         args[1].value.int32_value >= 0 && args[2].value.int32_value > 0 &&
         args[1].value.int32_value == args[2].value.int32_value - 1;
}

