    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Count the scratch used by typed builtin expansions.
    case IR_FX_ORD:
      return inst->result != IR_INVALID_ID;
    case IR_FX_TO_STR:
      return inst->result != IR_INVALID_ID &&
             cg_operand_type(fn, &inst->operands.call.args[0]) == (IrType)-1;
    case IR_FX_READ_LINE:
    case IR_FX_READ_INT:
    case IR_FX_READ_BOOL:
    case IR_FX_READ_DOUBLE:
